def generate(seed):
    r = random.Random(seed)
    n = r.randint(3, 6)
    out = ""
    while len(out) < n:
        w = r.choice(words.COMMON)
        k = words.vowels(w) if len(out) % 2 == 0 else words.consonants(w)
        if 1 <= k <= 9:
            out += str(k)
    return out

