def solve(clue):
    r = random.Random(clue)
    out = []
    for i, d in enumerate(clue):
        d = int(d)
        f = words.vowels if i % 2 == 0 else words.consonants
        out.append(words.pick(r, lambda w: f(w) == d and len(w) >= 3))
    return " ".join(out)

